def inversions(xs: list[int]) -> int:
    count = 0
    n = len(xs)
    for i in range(n):
        x = xs[i]
        for j in range(i + 1, n):
            if xs[j] < x:
                cnt += 1
    return count


def test_inversions():
    assert inversions([3, 1, 2]) == 2
    assert inversions([2, 2, 1]) == 2
    assert inversions([5, 4, 3, 2, 1]) == 10
    assert inversions([]) == 0
